<span class="line">  <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>template</span> <span class="token attr-name">#default</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{ validationResult }<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span></span>
