<span class="line">  <span class="token function">live</span><span class="token punctuation">(</span>path<span class="token punctuation">.</span>profile<span class="token punctuation">.</span><span class="token function">myProfile</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
