<span class="line">  <span class="token keyword">if</span><span class="token punctuation">(</span>draft<span class="token punctuation">.</span>value<span class="token punctuation">)</span> <span class="token keyword">await</span> actions<span class="token punctuation">.</span>draft<span class="token punctuation">.</span><span class="token function">resetMyDraft</span><span class="token punctuation">(</span>draftIdentifiers<span class="token punctuation">)</span></span>
